ecision.probability >= var.settings.required","manualExpression":true}},{"x":80,"y":1290,"id":"reply-8","type":"OPERATION","label":"Пометить: нужен ответ","config":{"section":"3. Метка ответа","arguments":{"clientId":"=client.id","required":true,"messageId":"=message.id"},"operation":"client.replyFlag","resultVariable":""}},{"x":80,"y":1540,"id":"reply-9","type":"CONDITION","label":"Вероятность ниже порога «ответ не нужен»?","config":{"rule":{"left":"=var.decision.probability","right":"=var.settings.notRequired","operator":"<="},"groups":[],"section":"3. Метка ответа","expression":"var.decision.probability <= var.settings.notRequired","manualExpression":true}},{"x":500,"y":1290,"id":"reply-10","type":"OPERATION","label":"Пометить: ответ не нужен","config":{"section":"3. Метка ответа","arguments":{"clientId":"=client.id","required":false,"messageId":"=message.id"},"operation":"client.replyFlag","resultVariable":""}},{"x":500,"y":820,"id":"reply-11","type":"END","label":"Ошибка — посмотреть журнал","config":{"result":"Шаг не выполнен. Причина указана в журнале.","section":"2. Оценка сообщения"}},{"x":920,"y":820,"id":"reply-12","type":"END","label":"На этом закончить","config":{"result":"Дополнительные действия не требуются","section":"2. Оценка сообщения"}},{"x":920,"y":1290,"id":"reply-13","type":"END","label":"На этом закончить","config":{"result":"Дополнительные действия не требуются","section":"3. Метка ответа"}},{"x":920,"y":1540,"id":"reply-14","type":"END","label":"Ошибка — посмотреть журнал","config":{"result":"Шаг не выполнен. Причина указана в журнале.","section":"3. Метка ответа"}}],"version":3,"entryNodeId":"reply-1"},"automation_rule_status":"ENABLED"},{"name":"Подбор статьи базы знаний (Jev)","action":"workflow.run()","folder_id":5,"expression":"true","description":"Прозрачный граф: настройки, данные, оценка, условия и отдельные действия. Изменяйте параметры и шаги в редакторе.","else_action":null,"order_number":12,"trigger_type":"MESSAGE_INCOMING","display_order":2,"stop_processing":false,"workflow_version":3,"workflow_definition":{"version":3,"entryNodeId":"knowledge-1","sectionOrder":[],"nodes":[{"id":"knowledge-1","type":"EVENT","label":"Когда запускать","x":80.0,"y":100.0,"config":{"section":"1. Настройки","triggerType":"MESSAGE_INCOMING"}},{"id":"knowledge-2","type":"PARAMETERS","label":"Настройки сценария","x":500.0,"y":100.0,"config":{"section":"1. Настройки","parameters":[{"max":1,"min":0,"help":"Ниже порога данные не меняются.","name":"threshold","type":"number","label":"Минимальная уверенность Jev","value":0.7,"migrationSetting":"suggestKnowledgeArticle"},{"max":1000,"min":1,"help":"","name":"articles","type":"number","label":"Максимум статей для выбора","value":100},{"max":3000,"min":1,"help":"","name":"excerpt","type":"number","label":"Символов описания статьи","value":200}],"description":"Начните с этого блока: здесь меняются пороги, интервалы и ограничения. Остальные шаги используют эти значения.","resultVariable":"settings"}},{"id":"knowledge-5","type":"OPERATION","label":"Загрузить статьи базы знаний","x":2180.0,"y":570.0,"config":{"section":"2. Найти статью","arguments":{"limit":"=var.settings.articles"},"operation":"data.articles","resultVariable":"articles"}},{"id":"knowledge-6","type":"OPERATION","label":"Выбрать подходящую статью","x":2600.0,"y":570.0,"config":{"section":"2. Найти статью","arguments":{"no":"Нет","yes":"Да","kind":"choice","state":"=var.sourceMessage.text","options":{"__none__":"Ни одна статья не подходит"},"question":"Какая статья поможет ответить ТОЛЬКО на это последнее входящее сообщение клиента? Не продолжай старые темы и не делай выводы из прежней переписки или заявок. Если сообщение не содержит вопроса или проблемы, либо подходящей статьи нет, выбери «Ни одна статья не подходит».","candidates":"=var.articles","labelExpression":"var.item.name + ': ' + var.item.text.truncate(var.settings.excerpt)"},"operation":"ai.decide","resultVariable":"decision"}},{"id":"knowledge-7","type":"CONDITION","label":"Ответ получен и уверенности достаточно?","x":3020.0,"y":570.0,"config":{"rule":{"all":[{"left":"=var.decision.available","operator":"true"},{"left":"=var.decision.probability","right":"=var.settings.threshold","operator":">="},{"left":"=var.decision.value","operator":"notNull"}]},"groups":[],"section":"2. Найти статью","expression":"var.decision.available && var.decision.probability >= var.settings.threshold && var.decision.value.notNull()","manualExpression":true}},{"id":"knowledge-8","type":"OPERATION","label":"Одна подсказка на входящее сообщение","x":80.0,"y":1290.0,"config":{"section":"3. Защита от повторных предложений","arguments":{"key":"knowledge-message:{{ var.sourceMessage.clientId }}:{{ var.sourceMessage.id }}"},"operation":"state.claim","resultVariable":"claim"}},{"id":"knowledge-9","type":"CONDITION","label":"Для этого сообщения подсказка ещё не запускалась?","x":500.0,"y":1290.0,"config":{"rule":{"left":"=var.claim.acquired","operator":"true"},"groups":[],"section":"3. Защита от повторных предложений","expression":"var.claim.acquired","manualExpression":true}},{"id":"knowledge-10","type":"OPERATION","label":"Сообщить оператору о найденной статье","x":920.0,"y":1290.0,"config":{"section":"3. Защита от повторных предложений","arguments":{"text":"Jev: к сообщению #{{ var.sourceMessage.id }} нашлась статья «{{ var.decision.value.name }}». Готовлю подсказку…","clientId":"=var.sourceMessage.clientId"},"operation":"client.note","resultVariable":""}},{"id":"knowledge-11","type":"OPERATION","label":"Разрешить повтор после ошибки комментария","x":1340.0,"y":1290.0,"config":{"section":"3. Защита от повторных предложений","arguments":{"key":"knowledge-message:{{ var.sourceMessage.clientId }}:{{ var.sourceMessage.id }}"},"operation":"state.release","resultVariable":""}},{"id":"knowledge-12","type":"OPERATION","label":"Сформулировать подсказку оператору","x":80.0,"y":2010.0,"config":{"section":"4. Подготовить ответ в фоне","arguments":{"p