rget":"outage-32","sourceHandle":"error"},{"id":"outage-edge-outage-18-error","source":"outage-18","target":"outage-32","sourceHandle":"error"},{"id":"outage-edge-outage-19-error","source":"outage-19","target":"outage-32","sourceHandle":"error"},{"id":"outage-edge-outage-20-error","source":"outage-20","target":"outage-32","sourceHandle":"error"},{"id":"outage-edge-outage-21-error","source":"outage-21","target":"outage-32","sourceHandle":"error"},{"id":"outage-edge-outage-23-error","source":"outage-23","target":"outage-32","sourceHandle":"error"},{"id":"outage-edge-outage-24-error","source":"outage-24","target":"outage-32","sourceHandle":"error"},{"id":"outage-edge-outage-25-error","source":"outage-25","target":"outage-32","sourceHandle":"error"},{"id":"outage-edge-outage-26-next","source":"outage-26","target":"outage-33","sourceHandle":"next"}],"nodes":[{"x":80,"y":100,"id":"outage-1","type":"EVENT","label":"Когда запускать","config":{"section":"1. Настройки","triggerType":"MESSAGE_INCOMING"}},{"x":500,"y":100,"id":"outage-2","type":"PARAMETERS","label":"Настройки сценария","config":{"section":"1. Настройки","parameters":[{"max":1,"min":0,"help":"","name":"analysis","type":"number","label":"Уверенность выбора сервиса и причины","value":0.7,"migrationSetting":"detectIncident"},{"max":10080,"min":0,"help":"","name":"window","type":"number","label":"Окно подсчёта, минут","value":15},{"max":10080,"min":0,"help":"","name":"clients","type":"number","label":"Минимум разных клиентов","value":3},{"max":10080,"min":0,"help":"","name":"alertClients","type":"number","label":"Минимум клиентов при тревоге мониторинга","value":2},{"max":1,"min":0,"help":"","name":"outage","type":"number","label":"Вероятность «это сбой»","value":0.7},{"max":10080,"min":0,"help":"","name":"cooldown","type":"number","label":"Пауза после срабатывания, минут","value":60},{"max":1,"min":0,"help":"","name":"sameProblem","type":"number","label":"Вероятность общей проблемы","value":0.6},{"max":10080,"min":0,"help":"","name":"p1Clients","type":"number","label":"Клиентов для P1","value":10},{"help":"Если выключено — только уведомление.","name":"createDraft","type":"boolean","label":"При срабатывании создавать черновик инцидента","value":false},{"max":10080,"min":1,"help":"","name":"p1Interval","type":"number","label":"Интервал обновлений P1, минут","value":15},{"max":10080,"min":1,"help":"","name":"p2Interval","type":"number","label":"Интервал обновлений P2, минут","value":30},{"max":10080,"min":1,"help":"","name":"p3Interval","type":"number","label":"Интервал обновлений P3, минут","value":60},{"max":10080,"min":1,"help":"","name":"p4Interval","type":"number","label":"Интервал обновлений P4, минут","value":120}],"description":"Начните с этого блока: здесь меняются пороги, интервалы и ограничения. Остальные шаги используют эти значения.","resultVariable":"settings"}},{"x":80,"y":570,"id":"inc-analyze","type":"OPERATION","label":"Jev: разметка сообщения","config":{"section":"2. Разметка и подсчёт обращений","arguments":{"analysisThreshold":"=var.settings.analysis"},"operation":"signal.analyze","resultVariable":"outage"}},{"x":500,"y":570,"id":"inc-c-answer","type":"CONDITION","label":"Jev ответил?","config":{"rule":{"left":"=var.outage","operator":"notNull"},"groups":[],"section":"2. Разметка и подсчёт обращений","expression":"var.outage.notNull()","manualExpression":true}},{"x":920,"y":570,"id":"inc-c-matched","type":"CONDITION","label":"Относится к открытому инциденту?","config":{"rule":{"left":"=var.outage.matchedIncidentId","operator":"notNull"},"groups":[],"section":"2. Разметка и подсчёт обращений","expression":"var.outage.matchedIncidentId.notNull()","manualExpression":true}},{"x":1340,"y":570,"id":"inc-attach-matched","type":"CONDITION","label":"Отметить: тот же инцидент","config":{"rule":{"left":"=var.settings.createDraft","operator":"true"},"section":"2. Разметка и подсчёт обращений","arguments":{},"expression":"var.settings.createDraft","resultVariable":"","manualExpression":true}},{"x":1340,"y":820,"id":"inc-c-outage","type":"CONDITION","label":"Это сбой с понятным сервисом?","config":{"rule":{"all":[{"left":"=var.outage.serviceId","operator":"notNull"},{"left":"=var.outage.probability","right":"=var.settings.outage","operator":">="}]},"groups":[],"section":"2. Разметка и подсчёт обращений","expression":"var.outage.serviceId.notNull() && var.outage.probability >= var.settings.outage","manualExpression":true}},{"x":1760,"y":570,"id":"inc-ignore","type":"OPERATION","label":"Не считать","config":{"section":"2. Разметка и подсчёт обращений","arguments":{"decision":"IGNORED","signalId":"=var.outage.signalId","incidentId":null},"operation":"signal.mark","resultVariable":""}},{"x":1760,"y":820,"id":"inc-count","type":"OPERATION","label":"Посчитать обращения в окне","config":{"section":"2. Разметка и подсчёт обращений","arguments":{"scope":"GLOBAL","signalId":"=var.outage.signalId","windowMinutes":"=var.settings.window"},"operation":"signal.count","resultVariable":"window"}},{"x":2180,"y":570,"id":"inc-c-threshold","type":"CONDITION","label":"Достаточно клиентов?","config":{"rule":{"any":[{"left":"=var.window.clients","right":"=var.settings.clients","operator":">="},{"all":[{"any":[{"left":"=var.outage.monitoringStatus","right":"WARNING","operator":"="},{"left":"=var.outage.monitoringStatus","right":"CRITICAL","operator":"="}]},{"left":"=var.window.clients","right":"=var.settings.alertClients","operator":">="}]}]},"groups":[],"section":"2. Разметка и подсчёт обращений","expression":"var.window.clients >= var.settings.clients || ((var.outage.monitoringStatus = 'WARNING' || var.outage.monitoringStatus = 'CRITICAL') && var.window.clients >= var.settings.alertClients)","manualExpression":true}},{"x":2600,"y":570,"id":"inc-counted","type":"OPERATION","label":"Учесть, порог не достигнут","config":{"section":"2. Разметка и подсчёт обращений","arguments":{"decision":"COUNTED","signalId":"=var.outage.signalId","incidentId":null},"operation":"signal.mark","resultVariable":""}},{"x":2600,"y":820,"id":"inc-cooldown","type":"OPERATION","label":"Проверить паузу после срабатывания","config":{"section":"2. Разметка и подсчёт обращений","arguments":{"minutes":"=var.settings.cooldown","signalId":"=var.outage.signalId","onlyWithIncident":"=var.settings.createDraft"},"operation":"signal.cooldown","resultVariable":"cooldown"}},{"x":3020,"y":570,"id":"inc-c-recent-incident","type":"CONDITION","label":"Недавний инцидент по этой проблеме?","config":{"rule":{"left":"=var.cooldown.incidentId","operator":"notNull"},"groups":[],"section":"2. Разметка и подсчёт обращений","expression":"var.cooldown.incidentId.notNull()","manualExpression":true}},{"x":3440,"y":570,"id":"inc-attach-recent","type":"CONDITION","label":"Отметить: недавний инцидент","config":{"rule":{"left":"=var.settings.createDraft","operator":"true"},"section":"2. Разметка и подсчёт обращений","arguments":{},"expression":"var.settings.createDraft","resultVariable":"","manualExpression":true}},{"x":3440,"y":820,"id":"inc-c-cooldown","type":"CONDITION","label":"Пауза ещё идёт?","config":{"rule":{"left":"=var.cooldown.active","operator":"true"},"groups":[],"section":"2. Разметка и подсчёт обращений","expression":"var.cooldown.active","manualExpression":true}},{"x":3860,"y":570,"id":"inc-in-cooldown","type":"OPERATION","label":"Пауза","config":{"section":"2. Разметка и подсчёт обращений","arguments":{"decision":"COOLDOWN","signalId":"=var.outage.signalId","incidentId":null},"operation":"signal.mark","resultVariable":""}},{"x":3860,"y":820,"id":"inc-verify","type":"OPERATION","label":"Jev: проверка пачки","config":{"section":"2. Разметка и подсчёт обращений","arguments":{"window":"=var.window","signalId":"=var.outage.signalId","analysisThreshold":"=var.settings.analysis"},"operation":"signal.verify","resultVariable":"verdict"}},{"x":4280,"y":570,"id":"inc-c-verified","type":"CONDITION","label":"Проверка выполнена?","config":{"rule":{"left":"=var.verdict","operator":"notNull"},"groups":[],"section":"2. Разметка и подсчёт обращений","expression":"var.verdict.notNull()","manualExpression":true}},{"x":4700,"y":570,"id":"inc-unverified","type":"OPERATION","label":"Учесть без проверки","config":{"section":"2. Разметка и подсчёт обращений","arguments":{"decision":"COUNTED","signalId":"=var.outage.signalId","incidentId":null},"operation":"signal.mark","resultVariable":""}},{"x":4700,"y":820,"id":"inc-c-same","type":"CONDITION","label":"Одна проблема?","config":{"rule":{"left":"=var.verdict.sameProblem","right":"=var.settings.sameProblem","operator":">="},"groups":[],"section":"2. Разметка и подсчёт обращений","expression":"var.verdict.sameProblem >= var.settings.sameProblem","manualExpression":true}},{"x":5120,"y":570,"id":"inc-rejected","type":"OPERATION","label":"Разные проблемы","config":{"section":"2. Разметка и подсчёт обращений","arguments":{"decision":"BATCH_REJECTED","signalId":"=var.outage.signalId","incidentId":null},"operation":"signal.mark","resultVariable":""}},{"x":5120,"y":820,"id":"inc-severity","type":"SET_VARIABLE","label":"Серьёзность по оценке Jev","config":{"name":"severity","section":"2. Разметка и подсчёт обращений","expression":"var.verdict.severity"}},{"x":5540,"y":570,"id":"inc-c-p1","type":"CONDITION","label":"P1 при малом числе клиентов?","config":{"rule":{"all":[{"left":"=var.severity","right":"P1","operator":"="},{"left":"=var.window.clients","right":"=var.settings.p1Clients","operator":"<"}]},"groups":[],"section":"2. Разметка и подсчёт обращений","expression":"var.severity = 'P1' && var.window.clients < var.settings.p1Clients","manualExpression":true}},{"x":5960,"y":570,"id":"inc-cap","type":"SET_VARIABLE","label":"Не выше P2","config":{"name":"severity","section":"2. Разметка и подсчёт обращений","expression":"'P2'"}},{"x":6380,"y":570,"id":"inc-trigger","type":"CONDITION","label":"Уведомить ответственных","config":{"rule":{"left":"=var.settings.createDraft","operator":"true"},"section":"2. Раз