о сервиса","config":{"section":"2. Сервис и активный инцидент","arguments":{"key":"monitoring-service:{{ service.id }}"},"operation":"lock.key","resultVariable":""}},{"x":920,"y":570,"id":"monitoring-start-7","type":"OPERATION","label":"Загрузить инциденты сервиса","config":{"section":"2. Сервис и активный инцидент","arguments":{"limit":1000,"serviceId":"=service.id"},"operation":"data.incidents","resultVariable":"incidents"}},{"x":1340,"y":570,"id":"monitoring-start-8","type":"OPERATION","label":"Отобрать: active","config":{"section":"2. Сервис и активный инцидент","arguments":{"items":"=var.incidents","limit":1,"where":"!(var.item.status in ['CLOSED','CANCELLED'])","sortBy":"id","descending":true},"operation":"list.select","resultVariable":"active"}},{"x":1760,"y":570,"id":"monitoring-start-9","type":"CONDITION","label":"Активный инцидент уже есть?","config":{"rule":{"left":"=var.active.size()","right":0,"operator":">"},"groups":[],"section":"2. Сервис и активный инцидент","expression":"var.active.size() > 0","manualExpression":true}},{"x":80,"y":1290,"id":"monitoring-start-10","type":"OPERATION","label":"Добавить заметку о событии мониторинга","config":{"section":"3. Запись в существующий инцидент","arguments":{"text":"Мониторинг: {{ problem.name }}. Важность {{ problem.severity }}. {{ problem.updateMessage }} {{ problem.updateAction }} {{ problem.updateUser }} {{ problem.url }}","incidentId":"=var.active.first().id"},"operation":"incident.note","resultVariable":""}},{"x":80,"y":2010,"id":"monitoring-start-11","type":"CONDITION","label":"Важности достаточно для нового инцидента?","config":{"rule":{"left":"=problem.severity","right":"=var.settings.createSeverity","operator":">="},"groups":[],"section":"4. Явные условия создания черновика","expression":"problem.severity >= var.settings.createSeverity","manualExpression":true}},{"x":500,"y":2010,"id":"monitoring-start-12","type":"OPERATION","label":"Получить сервис и ответственных","config":{"section":"4. Явные условия создания черновика","arguments":{"serviceId":"=service.id"},"operation":"data.service","resultVariable":"catalogService"}},{"x":920,"y":2010,"id":"monitoring-start-13","type":"OPERATION","label":"Посчитать затронутых клиентов","config":{"section":"4. Явные условия создания черновика","arguments":{"serviceId":"=service.id"},"operation":"data.affectedClients","resultVariable":"affected"}},{"x":1340,"y":2010,"id":"monitoring-start-14","type":"OPERATION","label":"Серьёзность по умолчанию","config":{"section":"4. Явные условия создания черновика","arguments":{"value":"P4"},"operation":"value.set","resultVariable":"severity"}},{"x":1760,"y":2010,"id":"monitoring-start-15","type":"OPERATION","label":"Интервал обновлений по умолчанию","config":{"section":"4. Явные условия создания черновика","arguments":{"value":"=var.settings.p4Interval"},"operation":"value.set","resultVariable":"interval"}},{"x":2180,"y":2010,"id":"monitoring-start-16","type":"CONDITION","label":"Авария максимальной важности и достаточно клиентов?","config":{"rule":{"all":[{"left":"=problem.severity","right":5,"operator":">="},{"left":"=var.affected","right":"=var.settings.p1Clients","operator":">="}]},"groups":[],"section":"4. Явные условия создания черновика","expression":"problem.severity >= 5 && var.affected >= var.settings.p1Clients","manualExpression":true}},{"x":2600,"y":2010,"id":"monitoring-start-17","type":"OPERATION","label":"Установить P1","config":{"section":"4. Явные условия создания черновика","arguments":{"value":"P1"},"operation":"value.set","resultVariable":"severity"}},{"x":3020,"y":2010,"id":"monitoring-start-18","type":"OPERATION","label":"Интервал P1","config":{"section":"4. Явные условия создания черновика","arguments":{"value":"=var.settings.p1Interval"},"operation":"value.set","resultVariable":"interval"}},{"x":2600,"y":2260,"id":"monitoring-start-19","type":"CONDITION","label":"Высокая важность или P1 ограничен числом клиентов?","config":{"rule":{"left":"=problem.severity","r