pdate-1","type":"EVENT","label":"Когда запускать","config":{"section":"1. Настройки","triggerType":"MONITORING_PROBLEM_UPDATED"}},{"x":500,"y":100,"id":"monitoring-update-2","type":"PARAMETERS","label":"Настройки сценария","config":{"section":"1. Настройки","parameters":[{"max":5,"min":0,"help":"Порог действует и при создании из обновления.","name":"createSeverity","type":"number","label":"Создавать инцидент при важности Zabbix от","value":4},{"max":1000000,"min":0,"help":"","name":"p1Clients","type":"number","label":"P1 только при числе затронутых клиентов от","value":10},{"max":10080,"min":1,"help":"","name":"p1Interval","type":"number","label":"Интервал обновлений P1, минут","value":15},{"max":10080,"min":1,"help":"","name":"p2Interval","type":"number","label":"Интервал обновлений P2, минут","value":30},{"max":10080,"min":1,"help":"","name":"p3Interval","type":"number","label":"Интервал обновлений P3, минут","value":60},{"max":10080,"min":1,"help":"","name":"p4Interval","type":"number","label":"Интервал обновлений P4, минут","value":120}],"description":"Начните с этого блока: здесь меняются пороги, интервалы и ограничения. Остальные шаги используют эти значения.","resultVariable":"settings"}},{"x":80,"y":570,"id":"monitoring-update-5","type":"CONDITION","label":"Проблема сопоставлена с сервисом?","config":{"rule":{"left":"=service.id","operator":"notNull"},"groups":[],"section":"2. Сервис и активный инцидент","expression":"service.id.notNull()","manualExpression":true}},{"x":500,"y":570,"id":"monitoring-update-6","type":"OPERATION","label":"Последовательно обработать события одного сервиса","config":{"section":"2. Сервис и активный инцидент","arguments":{"key":"monitoring-service:{{ service.id }}"},"operation":"lock.key","resultVariable":""}},{"x":920,"y":570,"id":"monitoring-update-7","type":"OPERATION","label":"Загрузить инциденты сервиса","config":{"section":"2. Сервис и активный инцидент","arguments":{"limit":1000,"serviceId":"=service.id"},"operation":"data.incidents","resultVariable":"incidents"}},{"x":1340,"y":570,"id":"monitoring-update-8","type":"OPERATION","label":"Отобрать: active","config":{"section":"2. Сервис и активный инцидент","arguments":{"items":"=var.incidents","limit":1,"where":"!(var.item.status in ['CLOSED','CANCELLED'])","sortBy":"id","descending":true},"operation":"list.select","resultVariable":"active"}},{"x":1760,"y":570,"id":"monitoring-update-9","type":"CONDITION","label":"Активный инцидент уже есть?","config":{"rule":{"left":"=var.active.size()","right":0,"operator":">"},"groups":[],"section":"2. Сервис и активный инцидент","expression":"var.active.size() > 0","manualExpression":true}},{"x":80,"y":1290,"id":"monitoring-update-10","type":"OPERATION","label":"Добавить заметку о событии мониторинга","config":{"section":"3. Запись в существующий инцидент","arguments":{"text":"Мониторинг: {{ problem.name }}. Важность {{ problem.severity }}. {{ problem.updateMessage }} {{ problem.updateAction }} {{ problem.updateUser }} {{ problem.url }}","incidentId":"=var.active.first().id"},"operation":"incident.note","resultVariable":""}},{"x":80,"y":2010,"id":"monitoring-update-11","type":"CONDITION","label":"Важности достаточно для нового инцидента?","config":{"rule":{"left":"=problem.severity","right":"=var.settings.createSeverity","operator":">="},"groups":[],"section":"4. Явные условия создания черновика","expression":"problem.severity >= var.settings.createSeverity","manualExpression":true}},{"x":500,"y":2010,"id":"monitoring-update-12","type":"CONDITION","label":"Проблема всё ещё открыта?","config":{"rule":{"left":"=problem.status","right":"OPEN","operator":"="},"groups":[],"section":"4. Явные условия создания черновика","expression":"problem.status = 'OPEN'","manualExpression":true}},{"x":920,"y":2010,"id":"monitoring-update-13","type":"OPERATION","label":"Получить сервис и ответственных","config":{"section":"4. Явные условия создания черновика","arguments":{"serviceId":"=service.id"},"operation":"data.se