и объявите инцидент.","participantIds":"=var.catalogService.executorIds","intervalMinutes":"=var.interval","publicDescription":"Наблюдаются проблемы с сервисом «{{ service.name }}». Мы разбираемся и сообщим новости."},"operation":"incident.create","resultVariable":"createdIncident"}},{"x":80,"y":2980,"id":"monitoring-update-27","type":"OPERATION","label":"Данные линии поддержки","config":{"section":"5. Получатели уведомлений","arguments":{},"operation":"data.lines","resultVariable":"allLines"}},{"x":500,"y":2980,"id":"monitoring-update-28","type":"OPERATION","label":"Отобрать: incidentLines","config":{"section":"5. Получатели уведомлений","arguments":{"items":"=var.allLines","limit":100,"where":"var.item.id = var.catalogService.lineId","sortBy":"id","descending":false},"operation":"list.select","resultVariable":"incidentLines"}},{"x":920,"y":2980,"id":"monitoring-update-29","type":"OPERATION","label":"Список участников линии по умолчанию","config":{"section":"5. Получатели уведомлений","arguments":{"value":[]},"operation":"value.set","resultVariable":"lineMembers"}},{"x":1340,"y":2980,"id":"monitoring-update-30","type":"CONDITION","label":"У сервиса есть линия?","config":{"rule":{"left":"=var.incidentLines.size()","right":0,"operator":">"},"groups":[],"section":"5. Получатели уведомлений","expression":"var.incidentLines.size() > 0","manualExpression":true}},{"x":1760,"y":2980,"id":"monitoring-update-31","type":"OPERATION","label":"Участники и ответственный линии","config":{"section":"5. Получатели уведомлений","arguments":{"first":"=var.incidentLines.first().memberIds","second":["=var.incidentLines.first().responsibleId"]},"operation":"list.concat","resultVariable":"lineMembers"}},{"x":2180,"y":2980,"id":"monitoring-update-32","type":"OPERATION","label":"Ответственные за сервис","config":{"section":"5. Получатели уведомлений","arguments":{"first":"=var.catalogService.executorIds","second":["=var.catalogService.ownerId"]},"operation":"list.concat","resultVariable":"recipientIds"}},{"x":2600,"y":2980,"id":"monitoring-update-33","type":"OPERATION","label":"Объединить ответственных сервиса и линии","config":{"section":"5. Получатели уведомлений","arguments":{"first":"=var.recipientIds","second":"=var.lineMembers"},"operation":"list.concat","resultVariable":"recipientIds"}},{"x":3020,"y":2980,"id":"monitoring-update-34","type":"OPERATION","label":"Отобрать: recipientIds","config":{"section":"5. Получатели уведомлений","arguments":{"items":"=var.recipientIds","limit":100,"where":"var.item.notNull()","sortBy":"","descending":false},"operation":"list.select","resultVariable":"recipientIds"}},{"x":3440,"y":2980,"id":"monitoring-update-35","type":"CONDITION","label":"Ответственные найдены?","config":{"rule":{"left":"=var.recipientIds.size()","right":0,"operator":">"},"groups":[],"section":"5. Получатели уведомлений","expression":"var.recipientIds.size() > 0","manualExpression":true}},{"x":3860,"y":2980,"id":"monitoring-update-36","type":"OPERATION","label":"Запасной вариант: пользователи системы","config":{"section":"5. Получатели уведомлений","arguments":{},"operation":"data.users","resultVariable":"users"}},{"x":4280,"y":2980,"id":"monitoring-update-37","type":"OPERATION","label":"Отобрать: admins","config":{"section":"5. Получатели уведомлений","arguments":{"items":"=var.users","limit":100,"where":"var.item.enabled && var.item.admin","sortBy":"id","descending":false},"operation":"list.select","resultVariable":"admins"}},{"x":4700,"y":2980,"id":"monitoring-update-38","type":"OPERATION","label":"Уведомить администраторов, если ответственных нет","config":{"section":"5. Получатели уведомлений","arguments":{"items":"=var.admins","expression":"var.item.id"},"operation":"list.project","resultVariable":"recipientIds"}},{"x":5120,"y":2980,"id":"monitoring-update-39","type":"FOR_EACH","label":"Уведомить каждого ответственного","config":{"section":"5. Получатели уведомлений","maxItems":100,"endNodeId":"monitoring-update-40","itemVariable":"rec