ig":{"result":"Шаг не выполнен. Причина указана в журнале.","section":"5. Получатели уведомлений"}},{"x":5540,"y":3230,"id":"monitoring-update-49","type":"END","label":"На этом закончить","config":{"result":"Дополнительные действия не требуются","section":"5. Получатели уведомлений"}}],"version":3,"entryNodeId":"monitoring-update-1"},"automation_rule_status":"ENABLED"}]}
$snapshot$::jsonb;
    item jsonb;
    folder_ids jsonb := '{}'::jsonb;
    known_folder_ids bigint[] := '{}'::bigint[];
    known_trigger_ids bigint[] := '{}'::bigint[];
    parent_folder_id bigint;
    target_folder_id bigint;
    target_trigger_id bigint;
    matches integer;
    container_id bigint;
    next_position integer;
    sibling record;
begin
    -- Маркер и резервные копии создаются в той же транзакции, что и перенос.
    if exists(select 1 from automation_layout_backup where migration_version=68) then return; end if;
    insert into automation_layout_backup(migration_version,folders)
        select 68,coalesce(jsonb_agg(to_jsonb(f) order by id),'[]'::jsonb) from automation_folder f;
    insert into automation_workflow_backup(trigger_id,migration_version,definition)
        select id,68,to_jsonb(t) from automation_trigger t on conflict do nothing;

    -- Родители идут раньше вложенных папок. Исходные ID используются только как ключи отображения.
    for item in select * from jsonb_array_elements(snapshot->'folders')
    loop
        parent_folder_id := (folder_ids->>(item->>'parent_id'))::bigint;
        if item->>'parent_id' is not null and parent_folder_id is null then
            raise exception 'Не найдена родительская папка для %', item->>'name';
        end if;
        select min(id),count(*) into target_folder_id,matches from automation_folder
            where name=item->>'name' and parent_id is not distinct from parent_folder_id;
        if matches>1 then raise exception 'Неоднозначное имя папки автоматизаций: %',item->>'name'; end if;
        if target_folder_id is null then
            insert into automation_folder(name,parent_id,collapsed,display_order)
                values(item->>'name',parent_folder_id,(item->>'collapsed')::boolean,(item->>'display_order')::integer)
                returning id into target_folder_id;
        else
            update automation_folder set collapsed=(item->>'collapsed')::boolean,display_order=(item->>'display_order')::integer
                where id=target_folder_id;
        end if;
        folder_ids := folder_ids || jsonb_build_object(item->>'id',target_folder_id);
        known_folder_ids := array_append(known_folder_ids,target_folder_id);
    end loop;

    for item in select * from jsonb_array_elements(snapshot->'triggers')
    loop
        target_folder_id := (folder_ids->>(item->>'folder_id'))::bigint;
        select min(id),count(*) into target_trigger_id,matches from automation_trigger where name=item->>'name';
        if matches>1 then raise exception 'Неоднозначное имя автоматизации: %',item->>'name'; end if;
        if target_trigger_id is null then
            insert into automation_trigger(name,description,trigger_type,expression,action,else_action,
                    workflow_definition,workflow_version,automation_rule_status,stop_processing,
                    order_number,display_order,folder_id,match_count,failure_count)
                values(item->>'name',item->>'description',item->>'trigger_type',item->>'expression',item->>'action',item->>'else_action',
                    item->>'workflow_definition',(item->>'workflow_version')::integer,item->>'automation_rule_status',
                    (item->>'stop_processing')::boolean,(item->>'order_number')::integer,(item->>'display_order')::integer,
                    target_folder_id,0,0)
                returning id into target_trigger_id;
        else
            update automation_trigger set description=item->>'description',trigger_type=item->>'trigger_type',
                expression=item->>'expression',action=item->>'action',else_action=item->>'else_action',
                workflow_definition=item->>'workflow_definition',workflow_version=(item->>'workflow_version')::integer,
                automation_rule_status=item->>'automation_rule_status',stop_processing=(item->>'stop_processing')::boolean,
                order_number=(item->>'order_number')::integer,display_order=(item->>'display_order')::integer,folder_id=target_folder_id
                where id=target_trigger_id;
        end if;
        known_trigger_ids := array_append(known_trigger_ids,target_trigger_id);
    end loop;

    -- Не удаляем пользовательские элементы. В затронутых контейнерах ставим их после элементов снимка.
    for container_id in select null::bigint union all select unnest(known_folder_ids)
    loop
        select coalesce(max(position),-1)+1 into next_position from (
            select display_order as position from automation_folder
                where id=any(known_folder_ids) and parent_id is not distinct from container_id
            union all
            select display_order from automation_trigger
                where id=any(known_trigger_ids) and folder_id is not distinct from container_id
        ) positions;
        for sibling in
            select 'FOLDER' as kind,id,display_order from automation_folder
                where not(id=any(known_folder_ids)) and parent_id is not distinct from container_id
            union all
            select 'TRIGGER',id,display_order from automation_trigger
                where not(id=any(known_trigger_ids)) and folder_id is not distinct from container_id
            order by display_order,kind,id
        loop
            if sibling.kind='FOLDER' then
                update automation_folder set display_order=next_position where id=sibling.id;
            else
                update automation_trigger set display_order=next_position where id=sibling.id;
            end if;
            next_position := next_position+1;
        end loop;
    end loop;

    -- Как в сохранении дерева из интерфейса: порядок выполнения равен чтению дерева сверху вниз.
    with recursive containers(id,path,ancestors) as (
        select null::bigint,'{}'::integer[],'{}'::bigint[]
        union all
        select f.id,c.path || f.display_order,c.ancestors || f.id
            from automation_folder f join containers c on f.parent_id is not distinct from c.id
            where not(f.id=any(c.ancestors))
    ), ranked as (
        select t.id,(row_number() over(order by c.path || t.display_order,t.id)-1)::integer as position
            from automation_trigger t join containers c on t.folder_id is not distinct from c.id
    )
    update automation_trigger t set order_number=r.position from ranked r where t.id=r.id;
end
$migration$;
